74	 */
75	
76	@RestController
77	@CrossOrigin(exposedHeaders = "errors, content-type")
78	@RequestMapping("/api")
79	public class OwnerRestControllerV1 implements OwnersApi {
80	
81	    /** Dedicated audit logger; a successful create emits a single line here with the new owner's key details. */
82	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
83	
84	    /** Dedicated notification logger; a successful create enqueues a welcome notification here carrying the new owner's id and member id. */
85	    private static final Logger NOTIFY = LoggerFactory.getLogger("NOTIFY");
86	
87	    /**
88	     * Source of the {@link OwnerCreatedEvent}'s {@code seq}: a process-wide, monotonically increasing counter across
89	     * every owner create, so the structured audit events carry a strictly ordered sequence regardless of which
90	     * controller instance handled the request.
91	     */
92	    private static final AtomicLong OWNER_CREATED_SEQUENCE = new AtomicLong();
93	
94	    /** Maximum number of owners a single city may contain; creating an owner in a full city is rejected. */
95	    private static final int MAX_OWNERS_PER_CITY = 50;
96	
97	    /** Once a city already holds at least this many owners (but is not yet full), a further create there is flagged with a capacity warning. */
98	    private static final int CAPACITY_WARNING_THRESHOLD = 40;
99	
100	    /** Maximum number of owners that may be created in a single day; creating an owner past this cap is rejected. */
101	    private static final int MAX_OWNERS_PER_DAY = 100;
102	
103	    /** Once more than this many owners already exist for a day, a further create for that day is flagged as a bulk signup. */
104	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
105	
106	    /** Request header carrying the client-supplied idempotency key for a create; see {@link #addOwner}. */
107	    private static final String IDEMPOTENCY_KEY_HEADER = "Idempotency-Key";
108	
109	    /**
110	     * Remembers, per idempotency key, the id of the owner the first create with that key produced, so a repeated
111	     * create with an already-seen key returns the original owner instead of creating a duplicate.
112	     */
113	    private final Map<String, Integer> idempotentOwnerIds = new ConcurrentHashMap<>();
114	
115	    /** Fixed public holidays the business-day roll skips: the adjusted registration date never lands on one of these. */
116	    private static final Set<LocalDate> PUBLIC_HOLIDAYS = Set.of(
117	        LocalDate.parse("2026-01-01"), LocalDate.parse("2026-01-26"), LocalDate.parse("2026-04-25"),
118	        LocalDate.parse("2026-12-25"), LocalDate.parse("2026-12-28"));
119	
120	    private final ClinicService clinicService;
121	
122	    private final OwnerMapper ownerMapper;
123	
124	    private final PetMapper petMapper;
125	
126	    private final VisitMapper visitMapper;
127	
128	    private final TelephoneNormalizer telephoneNormalizer;
129	
130	    private final AddressNormalizer addressNormalizer;
131	
132	    private final EmailNormalizer emailNormalizer;
133	
134	    private final IdentityKeyResolver identityKeyResolver;
135	
136	    private final HouseholdResolver householdResolver;
137	
138	    /** The current request, used to read the optional {@code Idempotency-Key} header on a create. */
139	    private final HttpServletRequest request;
140	
141	    public OwnerRestControllerV1(ClinicService clinicService,
142	                                 OwnerMapper ownerMapper,
143	                                 PetMapper petMapper,
144	                                 VisitMapper visitMapper,
145	                                 TelephoneNormalizer telephoneNormalizer,
146	                                 AddressNormalizer addressNormalizer,
147	                                 EmailNormalizer emailNormalizer,
148	                                 IdentityKeyResolver identityKeyResolver,
149	                                 HouseholdResolver householdResolver,
150	                                 HttpServletRequest request) {
151	        this.clinicService = clinicService;
152	        this.ownerMapper = ownerMapper;
153	        this.petMapper = petMapper;
154	        this.visitMapper = visitMapper;
155	        this.telephoneNormalizer = telephoneNormalizer;
156	        this.addressNormalizer = addressNormalizer;
157	        this.emailNormalizer = emailNormalizer;
158	        this.identityKeyResolver = identityKeyResolver;
159	        this.householdResolver = householdResolver;
160	        this.request = request;
161	    }
162	
163	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
164	    @Override
165	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
166	        Collection<Owner> owners;
167	        if (lastName != null) {
168	            owners = this.clinicService.findOwnerByLastName(lastName);
169	        } else {
170	            owners = this.clinicService.findAllOwners();
171	        }
172	        if (owners.isEmpty()) {
173	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
174	        }
175	        owners.forEach(this::populateHouseholdMemberCount);
176	        List<OwnerDto> ownerDtos = owners.stream().map(this::toOwnerDto).toList();
177	        return new ResponseEntity<>(ownerDtos, HttpStatus.OK);
178	    }
179	
180	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
181	    @Override
182	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
183	        Owner owner = this.clinicService.findOwnerById(ownerId);
184	        if (owner == null) {
185	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
186	        }
187	        populateHouseholdMemberCount(owner);
188	        return new ResponseEntity<>(toOwnerDto(owner), HttpStatus.OK);
189	    }
190	
191	    /**
192	     * Maps an owner to its DTO and stamps on the two derived values the mapper cannot produce on its own, each because
193	     * it depends on more than the single owner: the {@code identityKey} (see
194	     * {@link IdentityKeyResolver#deriveIdentityKey}), which is not a stored field of the owner, and the household-capped
195	     * {@code membershipLevel} (see {@link #cappedMembershipLevel}), which the mapper derives from the owner alone but
196	     * which the ceiling rule then caps against the owner's fellow household members. The capped level replaces the
197	     * mapper's uncapped one on the returned DTO.
198	     *
199	     * @param owner the owner to map
200	     * @return the owner DTO carrying its identity key and household-capped membership level
201	     */
202	    private OwnerDto toOwnerDto(Owner owner) {
203	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
204	        stampIdentity(ownerDto, owner);
205	        ownerDto.setMembershipLevel(cappedMembershipLevel(owner));
206	        return ownerDto;
207	    }
208	
209	    /**
210	     * Assembles and stamps the owner's version-2 {@code identity} object onto a mapped owner DTO. The three identifiers
211	     * are grouped under the nested {@code identity} object: the owner's {@code memberId} and {@code householdId} taken
212	     * straight off the owner, and the {@code identityKey} (see {@link IdentityKeyResolver#deriveIdentityKey}), which is
213	     * not a stored field of the owner and so is derived here. Kept as the single home for assembling the owner's
214	     * response identity so the shape of that identity is changed in one place.
215	     *
216	     * @param ownerDto the mapped owner DTO to stamp
217	     * @param owner    the owner the DTO was mapped from
218	     */
219	    private void stampIdentity(OwnerDto ownerDto, Owner owner) {
220	        OwnerIdentityDto identity = new OwnerIdentityDto();
221	        identity.setMemberId(owner.getMemberId());
222	        identity.setHouseholdId(owner.getHouseholdId());
223	        identity.setIdentityKey(identityKeyResolver.deriveIdentityKey(owner));
224	        ownerDto.setIdentity(identity);
225	    }
226	
227	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
228	    @Transactional
229	    @Override
230	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
231	        String idempotencyKey = request.getHeader(IDEMPOTENCY_KEY_HEADER);
232	        if (idempotencyKey != null && !idempotencyKey.isBlank()) {
233	            ResponseEntity<OwnerDto> replay = replayIdempotentCreate(idempotencyKey);
234	            if (replay != null) {
235	                return replay;
236	            }
237	        }
238	        Owner owner = createOwner(ownerFieldsDto);
239	        if (idempotencyKey != null && !idempotencyKey.isBlank()) {
240	            idempotentOwnerIds.put(idempotencyKey, owner.getId());
241	        }
242	        return createdOwnerResponse(owner);
243	    }
244	
245	    /**
246	     * Replays the create that a previously-seen {@code Idempotency-Key} produced. When the key has already created an
247	     * owner that still exists, the original owner is returned with {@code 200 OK} instead of a duplicate being created;
248	     * otherwise (key unseen, or its owner has since been removed) {@code null} is returned and the create proceeds
249	     * normally.
250	     *
251	     * @param idempotencyKey the client-supplied idempotency key from the request header
252	     * @return a {@code 200 OK} response carrying the original owner, or {@code null} when there is nothing to replay
253	     */
254	    private ResponseEntity<OwnerDto> replayIdempotentCreate(String idempotencyKey) {
255	        Integer existingId = idempotentOwnerIds.get(idempotencyKey);
256	        if (existingId == null) {
257	            return null;
258	        }
259	        Owner owner = this.clinicService.findOwnerById(existingId);
260	        if (owner == null) {
261	            return null;
262	        }
263	        populateHouseholdMemberCount(owner);
264	        return new ResponseEntity<>(toOwnerDto(owner), HttpStatus.OK);
265	    }
266	
267	    /**
268	     * Creates and persists a new owner from an incoming payload, applying every creation rule in order. The payload is
269	     * normalized and validated (see {@link #normalizeAndValidate}), mapped to an owner and stamped with its fields
270	     * derived at creation (see {@link #populateDerivedFields}); the duplicate guard then runs against those derived
271	     * fields (see {@link #requireUniqueIdentity}) before the soft-duplicate
272	     * flag is recorded (see {@link #flagPossibleDuplicate}); the owner is saved, its transient household member count
273	     * is resolved (see {@link #populateHouseholdMemberCount}) and the creation is audited (see
274	     * {@link #auditOwnerCreated}). The returned owner carries its generated id and every field a response needs.
275	     *
276	     * @param ownerFieldsDto the incoming owner payload, mutated in place during normalization
277	     * @return the newly created, persisted owner
278	     */
279	    private Owner createOwner(OwnerFieldsDto ownerFieldsDto) {
280	        normalizeAndValidate(ownerFieldsDto);
281	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
282	        populateDerivedFields(owner, ownerFieldsDto);
283	        requireUniqueIdentity(owner);
284	        flagPossibleDuplicate(owner, ownerFieldsDto);
285	        this.clinicService.saveOwner(owner);
286	        populateHouseholdMemberCount(owner);
287	        auditOwnerCreated(owner);
288	        enqueueWelcomeNotification(owner);
289	        return owner;
290	    }
291	
292	    /**
293	     * Enqueues a welcome notification for a newly created owner by emitting a single line to the dedicated
294	     * {@link #NOTIFY} logger, carrying the owner's id and its {@code memberId} so the notification can be addressed to
295	     * the new member.
296	     *
297	     * @param owner the newly created, persisted owner, with all its derived fields already in place
298	     */
299	    private void enqueueWelcomeNotification(Owner owner) {
300	        NOTIFY.info("welcome notification enqueued: id={} memberId={}", owner.getId(), owner.getMemberId());
301	    }
302	
303	    /**
304	     * Builds the {@code 201 Created} response for a newly created owner: the owner mapped to its DTO (carrying its
305	     * identity key, see {@link #toOwnerDto}) as the body, with a {@code Location} header pointing at the new owner's
306	     * canonical URL.
307	     *
308	     * @param owner the newly created, persisted owner
309	     * @return a {@code 201 Created} response carrying the owner DTO and its {@code Location} header
310	     */
311	    private ResponseEntity<OwnerDto> createdOwnerResponse(Owner owner) {
312	        OwnerDto ownerDto = toOwnerDto(owner);
313	        HttpHeaders headers = new HttpHeaders();
314	        headers.setLocation(UriComponentsBuilder.newInstance()
315	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
316	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
317	    }
318	
319	    /**
320	     * Emits the single audit line for a successfully created owner to the dedicated {@link #AUDIT} logger, recording
321	     * its id, member id and registration date alongside the membership level (see
322	     * {@link MembershipLevelResolver#deriveMembershipLevel}) derived purely for the audit trail.
323	     *
324	     * <p>In addition to the human-readable line, a single immutable structured event is emitted as JSON (see
325	     * {@link OwnerCreatedEvent}), carrying a monotonically increasing {@code seq} (see
326	     * {@link #OWNER_CREATED_SEQUENCE}), the owner's id, its primary identifier (see
327	     * {@link #primaryIdentifier(Owner)}) and its membership level under the {@code OWNER_CREATED} event type.
328	     *
329	     * @param owner the newly created, persisted owner, with all its derived fields already in place
330	     */
331	    private void auditOwnerCreated(Owner owner) {
332	        logOwnerCreated(owner);
333	        publishOwnerCreatedEvent(owner);
334	    }
335	
336	    /**
337	     * Emits the human-readable audit line for a successfully created owner to the dedicated {@link #AUDIT} logger,
338	     * recording its id, member id and registration date alongside the membership level (see
339	     * {@link MembershipLevelResolver#deriveMembershipLevel}) derived purely for the audit trail.
340	     *
341	     * @param owner the newly created, persisted owner, with all its derived fields already in place
342	     */
343	    private void logOwnerCreated(Owner owner) {
344	        AUDIT.info("owner created: id={} memberId={} registrationDate={} membershipLevel={}",
345	            owner.getId(), primaryIdentifier(owner), owner.getRegistrationDate(),
346	            MembershipLevelResolver.deriveMembershipLevel(owner));
347	    }
348	
349	    /**
350	     * Emits the single immutable structured {@link OwnerCreatedEvent} for a successfully created owner as JSON to the
351	     * dedicated {@link #AUDIT} logger, carrying a monotonically increasing {@code seq} (see
352	     * {@link #OWNER_CREATED_SEQUENCE}), the owner's id, its primary identifier (see {@link #primaryIdentifier(Owner)})
353	     * and its membership level under the {@code OWNER_CREATED} event type. Kept as the single home for building the
354	     * structured event so its schema is changed in one place.
355	     *
356	     * @param owner the newly created, persisted owner, with all its derived fields already in place
357	     */
358	    private void publishOwnerCreatedEvent(Owner owner) {
359	        OwnerCreatedEvent event = new OwnerCreatedEvent(OWNER_CREATED_SEQUENCE.incrementAndGet(),
360	            owner.getId(), primaryIdentifier(owner), cappedMembershipLevel(owner));
361	        AUDIT.info(event.toJson());
362	    }
363	
364	    /**
365	     * Returns the owner's primary identifier — the unified {@code memberId} the structured {@link OwnerCreatedEvent}
366	     * carries as the owner's identity.
367	     *
368	     * @param owner the newly created, persisted owner
369	     * @return the owner's member id
370	     */
371	    private String primaryIdentifier(Owner owner) {
372	        return owner.getMemberId();
373	    }
374	
375	    /**
376	     * Stamps onto a newly mapped owner every field derived at creation from the owner itself and from the owners that
377	     * already exist, in the order each field depends on. The {@code memberId} is derived from the owner's own
378	     * fields (see {@link IdentityKeyResolver#deriveMemberId}); the {@code namesakeCount} (see
379	     * {@link #countNamesakes}), {@code bulkSignupWarning} (see {@link #computeBulkSignupWarning}) and
380	     * {@code capacityWarning} (see {@link #computeCapacityWarning}) are snapshots of the existing owners taken before
381	     * this owner is saved, so none counts the new owner itself; and the shared
382	     * {@code householdId} is assigned last (see {@link #assignHouseholdId}), derived deterministically from the owner's
383	     * last name and postcode, so it is in place before the owner's household membership level is capped (see
384	     * {@link #cappedMembershipLevel}). The owner is mutated in place; the caller applies the duplicate guards and saves it.
385	     *
386	     * @param owner          the newly mapped owner about to be saved
387	     * @param ownerFieldsDto the incoming owner payload
388	     */
389	    private void populateDerivedFields(Owner owner, OwnerFieldsDto ownerFieldsDto) {
390	        owner.setMemberId(deriveUniqueMemberId(owner));
391	        owner.setNamesakeCount(countNamesakes(owner));
392	        owner.setBulkSignupWarning(computeBulkSignupWarning(owner.getRegistrationDate()));
393	        owner.setCapacityWarning(computeCapacityWarning(owner.getCity()));
394	        assignHouseholdId(owner);
395	    }
396	
397	    /**
398	     * Derives an owner's {@code memberId} and de-duplicates it against the owners that already exist. The base id
399	     * is the pure derivation (see {@link IdentityKeyResolver#deriveMemberId}); when it collides with an existing
400	     * owner's {@code memberId} it is suffixed with {@code -<n>}, taking the smallest {@code n} of 2 or more that
401	     * makes the whole id unique. Evaluated before the new owner is saved, so the collision check reflects only owners
402	     * that predate this create; distinct owners therefore always receive distinct member ids.
403	     *
404	     * @param owner the newly mapped owner about to be saved, with its telephone already normalized
405	     * @return the de-duplicated member id, unique across all existing owners
406	     */
407	    private String deriveUniqueMemberId(Owner owner) {
408	        String base = identityKeyResolver.deriveMemberId(owner);
409	        Collection<Owner> existing = this.clinicService.findAllOwners();
410	        String candidate = base;
411	        int n = 2;
412	        while (isMemberIdInUse(candidate, existing)) {
413	            candidate = base + "-" + n;
414	            n++;
415	        }
416	        return candidate;
417	    }
418	
419	    private boolean isMemberIdInUse(String memberId, Collection<Owner> existing) {
420	        return existing.stream().anyMatch(other -> memberId.equals(other.getMemberId()));
421	    }
422	
423	    /**
424	     * Prepares a new owner's payload for persistence, applying every rule an incoming owner must satisfy before it is
425	     * saved. The address is first normalized to its canonical stored form and written back onto the payload; required
426	     * fields are then checked (so an address that is blank after normalization is rejected); the telephone is
427	     * normalized to its canonical stored form, written back onto the payload and rejected if another owner already uses
428	     * it; the email is canonicalized; and the registration date is resolved to its effective business day. The
429	     * effective registration date is the supplied value or, when none was supplied, the current server date; when it
430	     * falls on a weekend it is rolled forward to the following Monday and that adjusted date is written back onto the
431	     * payload, so every value derived from it (such as the membership number's year segment and the per-day limit)
432	     * uses the adjusted date. The payload is mutated in place so the caller can map and save it directly. Duplicate
433	     * detection is deferred: it runs once, against the derived {@code identityKey}, after the household id has been
434	     * assigned (see {@link #requireUniqueIdentity}).
435	     *
436	     * @param ownerFieldsDto the incoming owner payload, mutated in place
437	     * @throws MissingOwnerFieldsException if any required field is missing or blank
438	     */
439	    private void normalizeAndValidate(OwnerFieldsDto ownerFieldsDto) {
440	        normalizeAddress(ownerFieldsDto);
441	        validateRequiredFields(ownerFieldsDto);
442	        validatePostcode(ownerFieldsDto);
443	        String telephone = telephoneNormalizer.normalize(ownerFieldsDto.getTelephone());
444	        ownerFieldsDto.setTelephone(telephone);
445	        requireCityHasCapacity(ownerFieldsDto.getCity());
446	        LocalDate registrationDate = resolveRegistrationDate(ownerFieldsDto);
447	        ownerFieldsDto.setRegistrationDate(registrationDate);
448	        requireDailyLimitNotReached(registrationDate);
449	        normalizeEmail(ownerFieldsDto);
450	    }
451	
452	    /**
453	     * Normalizes an owner's address to its canonical stored form and writes it back onto the payload. The structured
454	     * form is preferred over the flat one: when a non-blank {@code addressLine1} is supplied it (and the optional
455	     * {@code addressLine2}) are normalized (see {@link AddressNormalizer#normalize}) and the flat {@code address} is
456	     * recomposed as the normalized {@code addressLine1}, with a single space and the normalized {@code addressLine2}
457	     * appended when {@code addressLine2} is present. Otherwise the flat {@code address} is normalized on its own and the
458	     * structured fields are cleared. Either way the canonical {@code address} is what gets stored and returned and what
459	     * every downstream reader uses; a blank result is uniformly treated as a missing address by the required-field
460	     * check that follows (an owner is valid when it supplies either a non-blank {@code addressLine1} or a non-blank flat
461	     * {@code address}). The payload is mutated in place so the caller can map and save it directly.
462	     *
463	     * @param ownerFieldsDto the incoming owner payload, mutated in place
464	     */
465	    private void normalizeAddress(OwnerFieldsDto ownerFieldsDto) {
466	        String line1 = addressNormalizer.normalize(ownerFieldsDto.getAddressLine1());
467	        String line2 = addressNormalizer.normalize(ownerFieldsDto.getAddressLine2());
468	        if (!line1.isEmpty()) {
469	            ownerFieldsDto.setAddressLine1(line1);
470	            ownerFieldsDto.setAddressLine2(line2.isEmpty() ? null : line2);
471	            ownerFieldsDto.setAddress(line2.isEmpty() ? line1 : line1 + " " + line2);
472	        }
473	        else {
474	            ownerFieldsDto.setAddressLine1(null);
475	            ownerFieldsDto.setAddressLine2(null);
476	            ownerFieldsDto.setAddress(addressNormalizer.normalize(ownerFieldsDto.getAddress()));
477	        }
478	    }
