492	    /**
493	     * Resolves an owner's effective registration date and rolls it onto a business day. The effective date is the value
494	     * supplied on the payload, or the current server date when none was supplied; when that date is a Saturday, a Sunday
495	     * or a listed public holiday (see {@link #PUBLIC_HOLIDAYS}) it is rolled forward one day at a time until it lands on
496	     * a non-holiday weekday. The returned date is always a business day. A supplied date later than the current server
497	     * date is rejected.
498	     *
499	     * @param ownerFieldsDto the incoming owner payload
500	     * @return the effective registration date rolled forward onto a business day
501	     * @throws FutureRegistrationDateException if a supplied registration date is later than the current server date
502	     */
503	    private LocalDate resolveRegistrationDate(OwnerFieldsDto ownerFieldsDto) {
504	        LocalDate effective = ownerFieldsDto.getRegistrationDate();
505	        if (effective == null) {
506	            effective = LocalDate.now();
507	        }
508	        else if (effective.isAfter(LocalDate.now())) {
509	            throw new FutureRegistrationDateException(
510	                "the registration date must not be later than the current server date");
511	        }
512	        while (effective.getDayOfWeek() == DayOfWeek.SATURDAY || effective.getDayOfWeek() == DayOfWeek.SUNDAY
513	            || PUBLIC_HOLIDAYS.contains(effective)) {
514	            effective = effective.plusDays(1);
515	        }
516	        return effective;
517	    }
