631	    /**
632	     * Rejects creating an owner whose whole derived {@code identityKey} (see
633	     * {@link IdentityKeyResolver#deriveIdentityKey}) equals that of an existing owner, so an owner is an identity
634	     * duplicate only when its normalized telephone, email and last-name Soundex all match another owner's. This single
635	     * identity key is now the sole duplicate rule: because the telephone is part of the key, owners that share only
636	     * their last name and postcode but carry different telephones have distinct keys and are not caught here — they are
637	     * created and flagged as a soft match instead (see {@link #flagPossibleDuplicate}), their membership level being
638	     * capped where they join an existing household (see {@link #cappedMembershipLevel}). Owners that have been
639	     * soft-deleted (see {@link #deleteOwner}) are ignored, so a matching identity that belongs only to a deleted owner
640	     * does not block the create.
641	     *
642	     * @param owner the newly mapped owner about to be saved, with its normalized fields already in place
643	     * @throws DuplicateOwnerException if any existing owner already has the same identity key
644	     */
645	    private void requireUniqueIdentity(Owner owner) {
646	        String identityKey = identityKeyResolver.deriveIdentityKey(owner);
647	        boolean inUse = this.clinicService.findAllOwners().stream()
648	            .filter(existing -> !existing.isDeleted())
649	            .anyMatch(existing -> identityKey.equals(identityKeyResolver.deriveIdentityKey(existing)));
650	        if (inUse) {
651	            throw new DuplicateOwnerException("an owner with the same identity key already exists");
652	        }
653	    }
