655	    /**
656	     * Flags a newly created owner as a possible (soft) duplicate. The owner has already cleared the hard-duplicate
657	     * guard (see {@link #requireUniqueIdentity}), so it is still being created; this only records a warning. A declared
658	     * household member (one created with {@code sharesHousehold} set to {@code true}) is never flagged: it deliberately
659	     * shares its household's last name and postcode, so it is not a suspected duplicate. Otherwise it is a possible
660	     * duplicate when some existing owner shares its last-name Soundex (see {@link SoundexResolver#soundex}) and its
661	     * postcode but has a different {@code identityKey}. When such an owner is found, {@code possibleDuplicate} is set to {@code true} and
662	     * {@code possibleDuplicateOf} to that existing owner's id (the first match in
663	     * {@link ClinicService#findAllOwners()} order); otherwise {@code possibleDuplicate} is {@code false} and
664	     * {@code possibleDuplicateOf} is left null. An owner created without a postcode can never soft-match.
665	     *
666	     * @param owner          the newly mapped owner about to be saved, with its normalized fields already in place
667	     * @param ownerFieldsDto the incoming owner payload
668	     */
669	    private void flagPossibleDuplicate(Owner owner, OwnerFieldsDto ownerFieldsDto) {
670	        owner.setPossibleDuplicate(false);
671	        if (Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
672	            return;
673	        }
674	        String postcode = owner.getPostcode();
675	        if (postcode == null || postcode.isBlank()) {
676	            return;
677	        }
678	        for (Owner existing : this.clinicService.findAllOwners()) {
679	            if (isPossibleDuplicateOf(owner, existing)) {
680	                owner.setPossibleDuplicate(true);
681	                owner.setPossibleDuplicateOf(existing.getId());
682	                return;
683	            }
684	        }
685	    }
