687	    /**
688	     * Decides whether {@code existing} makes {@code owner} a possible (soft) duplicate: some other owner whose last-name
689	     * Soundex (see {@link SoundexResolver#soundex}) and postcode both match {@code owner}'s but whose derived
690	     * {@code identityKey} (see {@link IdentityKeyResolver#deriveIdentityKey}) differs. An equal identity key would make
691	     * the two a hard duplicate, already rejected by {@link #requireUniqueIdentity}; a differing key with a matching
692	     * name-sound and postcode — for instance two owners sharing a last name and postcode but carrying different
693	     * telephones — is the soft match this flags. The postcode-present guard is applied by the caller (see
694	     * {@link #flagPossibleDuplicate}), so {@code owner}'s postcode is non-blank here.
695	     *
696	     * @param owner    the newly mapped owner about to be saved, with its normalized fields already in place
697	     * @param existing an already-persisted owner to test the new owner against
698	     * @return {@code true} when {@code existing} makes {@code owner} a possible duplicate
699	     */
700	    private boolean isPossibleDuplicateOf(Owner owner, Owner existing) {
701	        return SoundexResolver.soundex(owner.getLastName()).equals(SoundexResolver.soundex(existing.getLastName()))
702	            && owner.getPostcode().equals(existing.getPostcode())
703	            && !identityKeyResolver.deriveIdentityKey(owner).equals(identityKeyResolver.deriveIdentityKey(existing));
704	    }
