767	    /**
768	     * Returns an owner's household-capped membership level: the level the {@link MembershipLevelResolver} derives from
769	     * the owner (see {@link MembershipLevelResolver#deriveMembershipLevel(Owner)}), lowered where necessary so it never
770	     * exceeds one above the highest capped level among the owner's <em>existing</em> household members — the members
771	     * that predate the owner, identified as those sharing its non-null {@code householdId} with a smaller id. When the
772	     * owner has no such existing household member (it is the first in its household, or has no household at all) no cap
773	     * applies and the derived level is returned unchanged. The owner's transient household member count is populated
774	     * first (see {@link #populateHouseholdMemberCount}) so the derived level reflects the current household size.
775	     *
776	     * @param owner the owner whose capped membership level should be computed
777	     * @return the membership level, capped at one above the existing household maximum
778	     */
779	    private int cappedMembershipLevel(Owner owner) {
780	        populateHouseholdMemberCount(owner);
781	        int level = MembershipLevelResolver.deriveMembershipLevel(owner);
782	        Integer cap = householdMembershipLevelCap(owner);
783	        return cap == null ? level : Math.min(level, cap);
784	    }
785	
786	    /**
787	     * Computes the ceiling the {@link #cappedMembershipLevel level-ceiling rule} imposes on a new owner: one above the
788	     * highest capped membership level among the owner's existing household members, or {@code null} when there is none.
789	     * An existing household member is an owner sharing this owner's non-null {@code householdId} whose id is smaller (so
790	     * it predates this owner); their levels are read with {@link #cappedMembershipLevel}, so each member's own ceiling
791	     * is respected in turn. An owner with no household ({@code null} householdId), no id yet, or no existing household
792	     * member has no cap.
793	     *
794	     * @param owner the owner whose household level cap should be computed
795	     * @return one above the existing household maximum level, or {@code null} when no cap applies
796	     */
797	    private Integer householdMembershipLevelCap(Owner owner) {
798	        String householdId = owner.getHouseholdId();
799	        Integer id = owner.getId();
800	        if (householdId == null || id == null) {
801	            return null;
802	        }
803	        Integer maxLevel = null;
804	        for (Owner member : this.clinicService.findAllOwners()) {
805	            Integer memberId = member.getId();
806	            if (memberId != null && memberId < id && householdId.equals(member.getHouseholdId())) {
807	                int memberLevel = cappedMembershipLevel(member);
808	                maxLevel = (maxLevel == null) ? memberLevel : Math.max(maxLevel, memberLevel);
809	            }
810	        }
811	        return maxLevel == null ? null : maxLevel + 1;
812	    }
