814	    /**
815	     * Returns the owners that belong to the given owner's household: those sharing the same non-null
816	     * {@code householdId}. An owner with no household ({@code null} householdId) is a household of one and is returned on
817	     * its own. The lookup runs against {@link ClinicService#findAllOwners()} and, like the household member count it
818	     * backs (see {@link #populateHouseholdMemberCount}), does not exclude soft-deleted owners. When the owner has
819	     * already been saved it is itself among the members returned.
820	     *
821	     * @param owner the owner whose household members should be resolved
822	     * @return the members of the owner's household, never empty
823	     */
824	    private List<Owner> householdMembers(Owner owner) {
825	        String householdId = owner.getHouseholdId();
826	        if (householdId == null) {
827	            return List.of(owner);
828	        }
829	        return this.clinicService.findAllOwners().stream()
830	            .filter(existing -> householdId.equals(existing.getHouseholdId()))
831	            .toList();
832	    }
