303	    /**
304	     * Builds the response body shared by the handlers that report a single business-rule violation: a
305	     * {@link ProblemDetail} for the given status carrying {@code detail} as its detail message and the offending field
306	     * names in its {@code errors} property.
307	     *
308	     * @param e the exception being handled, used to title the {@link ProblemDetail}
309	     * @param status the HTTP status to return
310	     * @param request {@link HttpServletRequest} object referring to the current request.
311	     * @param detail the human-readable detail message
312	     * @param errors the names of the fields the violation is reported against
313	     * @return a {@link ResponseEntity} carrying the problem detail and the given status
314	     */
315	    private ResponseEntity<ProblemDetail> errorResponse(Exception e, HttpStatus status, HttpServletRequest request,
316	                                                        String detail, List<String> errors) {
317	        ProblemDetail problemDetail = this.detailBuild(e, status, request.getRequestURL(), detail);
318	        problemDetail.setProperty("errors", errors);
319	        return ResponseEntity.status(status).body(problemDetail);
320	    }
