18	
19	/**
20	 * Immutable structured audit event recording that an owner was created. Emitted to the dedicated {@code AUDIT} logger as
21	 * a JSON object alongside the human-readable audit line (see
22	 * {@link OwnerRestControllerV1#auditOwnerCreated(org.springframework.samples.petclinic.model.Owner)}).
23	 *
24	 * <p>The event carries the owner's primary identifier in its {@code primaryId} field: the unified {@code memberId}. The
25	 * field records "the owner's identity" rather than any one named column, and is rendered under the {@code memberId} JSON
26	 * key, matching the identifier it carries.
27	 *
28	 * @param seq         monotonically increasing sequence number across all owner creates
29	 * @param ownerId     the newly created owner's generated id
30	 * @param primaryId   the owner's primary identifier (the {@code memberId})
31	 * @param membershipLevel the owner's membership level at creation
32	 */
33	record OwnerCreatedEvent(long seq, Integer ownerId, String primaryId, int membershipLevel) {
34	
35	    /** The fixed {@code event} discriminator every owner-created event carries. */
36	    static final String EVENT_TYPE = "OWNER_CREATED";
37	
38	    /** The schema version this structured event is emitted under; bumped to 2 for the version-2 owner identity. */
39	    static final int SCHEMA_VERSION = 2;
40	
41	    /**
42	     * Renders this event as a compact JSON object
43	     * {@code {seq, schemaVersion:2, ownerId, memberId, membershipLevel, event:'OWNER_CREATED'}}, with the primary
44	     * identifier (the version-2 {@code memberId}) under the {@code memberId} key. String values are JSON-escaped; a
45	     * {@code null} identifier is rendered as JSON {@code null}.
46	     *
47	     * @return the event serialized as a single-line JSON object
48	     */
49	    String toJson() {
50	        return "{"
51	            + "\"seq\":" + seq
52	            + ",\"schemaVersion\":" + SCHEMA_VERSION
53	            + ",\"ownerId\":" + ownerId
54	            + ",\"memberId\":" + jsonString(primaryId)
55	            + ",\"membershipLevel\":" + membershipLevel
56	            + ",\"event\":" + jsonString(EVENT_TYPE)
57	            + "}";
58	    }
59	
60	    private static String jsonString(String value) {
61	        if (value == null) {
62	            return "null";
63	        }
64	        StringBuilder sb = new StringBuilder(value.length() + 2);
65	        sb.append('"');
66	        for (int i = 0; i < value.length(); i++) {
67	            char c = value.charAt(i);
68	            switch (c) {
69	                case '"' -> sb.append("\\\"");
70	                case '\\' -> sb.append("\\\\");
71	                case '\n' -> sb.append("\\n");
72	                case '\r' -> sb.append("\\r");
73	                case '\t' -> sb.append("\\t");
74	                default -> {
75	                    if (c < 0x20) {
76	                        sb.append(String.format("\\u%04x", (int) c));
77	                    }
78	                    else {
79	                        sb.append(c);
80	                    }
81	                }
82	            }
83	        }
84	        sb.append('"');
85	        return sb.toString();
86	    }
87	}
