18	
19	import org.springframework.samples.petclinic.rest.advice.DisposableEmailException;
20	import org.springframework.stereotype.Component;
21	
22	/**
23	 * Turns owner emails into the single canonical form that gets stored, returned and compared, so the REST controllers do
24	 * not have to carry the email rules themselves.
25	 *
26	 * <p>A syntactically valid address is already enforced by Bean Validation on the request payload, so normalization only
27	 * canonicalizes the value by lower-casing it. So {@code "Owner@Example.TEST"} becomes {@code "owner@example.test"}.
28	 *
29	 * <p>Normalization also rejects any address whose domain is on the disposable-domain blocklist
30	 * ({@code mailinator.com}, {@code tempmail.com}, {@code guerrillamail.com}), since such throwaway addresses are not
31	 * acceptable owner contacts. The comparison is case-insensitive because the value is canonicalized (lower-cased) first.
32	 *
33	 * <p>Unlike the address and telephone, an email is optional: a missing (blank or {@code null}) value is left untouched,
34	 * so callers can uniformly treat a blank result as a missing email. The same canonical form is used both for the value
35	 * that is stored and returned and for every email comparison (such as duplicate detection across existing owners), so
36	 * incidental case differences never affect the outcome.
37	 */
38	@Component
39	public class EmailNormalizer {
40	
41	    /**
42	     * Normalizes an owner email into its canonical stored form by lower-casing it. A missing (blank or {@code null})
43	     * email is returned untouched, since the field is optional. The normalized value is what gets stored and returned as
44	     * {@code email}, and the same form is used when comparing an owner's email against those of existing owners. An
45	     * email whose domain is on the disposable-domain blocklist is rejected.
46	     *
47	     * @param email the raw email value from the request, may be {@code null}
48	     * @return the lower-cased email, or the original value when none was supplied
49	     * @throws DisposableEmailException if the email's domain is on the disposable-domain blocklist
50	     */
51	    public String normalize(String email) {
52	        if (email == null || email.isBlank()) {
53	            return email;
54	        }
55	        String normalized = email.toLowerCase();
56	        rejectDisposableDomain(normalized);
57	        return normalized;
58	    }
59	
60	    /**
61	     * Rejects a normalized email whose domain (the part after the final {@code '@'}) is on the disposable-domain
62	     * blocklist. An address without a domain part is left to Bean Validation's syntactic check and passes here.
63	     *
64	     * @param normalized the lower-cased email
65	     * @throws DisposableEmailException if the domain is on the disposable-domain blocklist
66	     */
67	    private void rejectDisposableDomain(String normalized) {
68	        int at = normalized.lastIndexOf('@');
69	        if (at < 0) {
70	            return;
71	        }
72	        String domain = normalized.substring(at + 1);
73	        if (DisposableEmailPolicy.isBlocked(domain)) {
74	            throw new DisposableEmailException(
75	                "email domain " + domain + " is on the disposable-domain blocklist");
76	        }
77	    }
78	}
