17	package org.springframework.samples.petclinic.rest.validation;
18	
19	import java.util.Set;
20	
21	/**
22	 * Single source of truth for the throwaway-email policy an owner's email is judged against. The blocklist of disposable
23	 * providers ({@code mailinator.com}, {@code tempmail.com}, {@code guerrillamail.com}) is enforced two ways:
24	 *
25	 * <ul>
26	 *   <li>an email whose domain is <em>exactly</em> a blocklisted domain is rejected outright at create (see
27	 *       {@link EmailNormalizer#normalize}), so such an address is never stored; and</li>
28	 *   <li>an email whose domain is not itself blocklisted but is closely related to a blocklisted one is
29	 *       <em>disposable-adjacent</em> (see {@link #isDisposableAdjacent}) — accepted, but treated as a risk signal.</li>
30	 * </ul>
31	 *
32	 * <p>Kept a static utility (like the mapper's resolvers) so both the create-time rejection and the read-time risk flag
33	 * derive from one blocklist and can never drift apart. Comparisons are case-insensitive; callers normalize the email to
34	 * lower case first.
35	 */
36	public final class DisposableEmailPolicy {
37	
38	    /** Domains of throwaway email providers that an owner's email may not use verbatim, and whose look-alikes are risky. */
39	    static final Set<String> DISPOSABLE_DOMAINS = Set.of(
40	        "mailinator.com", "tempmail.com", "guerrillamail.com");
41	
42	    private DisposableEmailPolicy() {
43	    }
44	
45	    /**
46	     * Returns whether {@code domain} is exactly on the disposable-domain blocklist. The comparison is case-insensitive.
47	     *
48	     * @param domain the email domain (the part after the final {@code '@'}), may be {@code null}
49	     * @return {@code true} when the domain is a blocklisted disposable domain
50	     */
51	    public static boolean isBlocked(String domain) {
52	        return domain != null && DISPOSABLE_DOMAINS.contains(domain.toLowerCase());
53	    }
54	
55	    /**
56	     * Returns whether {@code email}'s domain is disposable-adjacent: not itself on the blocklist, but closely related to
57	     * a blocklisted disposable domain. A domain is disposable-adjacent when it is either
58	     *
59	     * <ul>
60	     *   <li>a subdomain of a blocklisted domain (for example {@code inbox.mailinator.com}); or</li>
61	     *   <li>a look-alike sharing a blocklisted domain's second-level label under a different top-level domain (for
62	     *       example {@code mailinator.net} or {@code tempmail.io}).</li>
63	     * </ul>
64	     *
65	     * <p>A missing (blank or {@code null}) email, or one without a domain part, is never disposable-adjacent. The check
66	     * is case-insensitive.
67	     *
68	     * @param email the owner's email, may be {@code null}
69	     * @return {@code true} when the email's domain is disposable-adjacent
70	     */
71	    public static boolean isDisposableAdjacent(String email) {
72	        if (email == null || email.isBlank()) {
73	            return false;
74	        }
75	        int at = email.lastIndexOf('@');
76	        if (at < 0) {
77	            return false;
78	        }
79	        String domain = email.substring(at + 1).toLowerCase();
80	        if (domain.isEmpty() || DISPOSABLE_DOMAINS.contains(domain)) {
81	            return false;
82	        }
83	        String label = secondLevelLabel(domain);
84	        for (String blocked : DISPOSABLE_DOMAINS) {
85	            if (domain.endsWith("." + blocked) || label.equals(secondLevelLabel(blocked))) {
86	                return true;
87	            }
88	        }
89	        return false;
90	    }
91	
92	    /** The label before the first dot of a domain, e.g. {@code "mailinator"} for both {@code mailinator.com} and {@code mailinator.net}. */
93	    private static String secondLevelLabel(String domain) {
94	        int dot = domain.indexOf('.');
95	        return dot < 0 ? domain : domain.substring(0, dot);
96	    }
97	}
