1	package org.springframework.samples.petclinic.mapper;
2	
3	import org.springframework.stereotype.Component;
4	
5	/**
6	 * Derives the shared {@code householdId} that every owner in the same household resolves to. The household is keyed on
7	 * the owner's last name and postcode, so the identifier is a pure, deterministic function of those two fields and every
8	 * owner sharing them resolves to the same value automatically, regardless of creation order. Kept here (rather than in
9	 * {@link OwnerMapper} or the REST controller) mirrors {@link IdentityKeyResolver}, {@link LocalityResolver} and
10	 * {@link MembershipLevelResolver} and gives household derivation a single home.
11	 */
12	@Component
13	public class HouseholdResolver {
14	
15	    /**
16	     * Derives a household's stable identifier: the first 12 hex characters of the SHA-256 digest of the fixed version-2
17	     * {@link IdentityKeyResolver#VERSION_TAG}, the normalized last name and the postcode, joined with {@code '|'}
18	     * separators. Mixing in the shared version tag rederives the identifier under the version-2 owner identity so no
19	     * value produced under version 1 recurs. The last name is normalized by trimming it, collapsing every run of
20	     * whitespace to a single space and lower-casing it; the postcode is used as given (an empty string when none). Being
21	     * a pure function of the last name and postcode, it is identical for every owner in the same household and never
22	     * changes over time.
23	     *
24	     * @param lastName the household's last name
25	     * @param postcode the household's postcode, may be {@code null}
26	     * @return the household identifier
27	     */
28	    public String deriveHouseholdId(String lastName, String postcode) {
29	        String key = IdentityKeyResolver.VERSION_TAG + "|" + collapseWhitespace(lastName).toLowerCase() + "|"
30	            + (postcode == null ? "" : postcode);
31	        return HexDigest.upperHexPrefix(key, 12);
32	    }
33	
34	    /**
35	     * Canonicalizes a value for household comparison by trimming it and collapsing every run of whitespace to a single
36	     * space. Case is deliberately preserved here; {@link #deriveHouseholdId} lower-cases the result itself.
37	     *
38	     * @param value the raw field value, may be {@code null}
39	     * @return the whitespace-collapsed value, or an empty string when {@code null}
40	     */
41	    public String collapseWhitespace(String value) {
42	        if (value == null) {
43	            return "";
44	        }
45	        return value.strip().replaceAll("\\s+", " ");
46	    }
47	}
