2	
3	import java.time.LocalDate;
4	
5	import org.springframework.samples.petclinic.model.Owner;
6	
7	/**
8	 * Derives an owner's 'membershipPoints' and numeric 'membershipLevel', assigned
9	 * on create. Kept out of {@link OwnerMapper} so MapStruct does not mistake it for
10	 * an implicit property mapping method.
11	 */
12	public final class MembershipLevelResolver {
13	
14	    /** Points awarded when an email is present (non-blank). */
15	    private static final int EMAIL_POINTS = 2;
16	
17	    /** Points awarded when the owner's name was unique on create (namesakeCount is 0). */
18	    private static final int UNIQUE_NAME_POINTS = 1;
19	
20	    /** Points awarded for a household of three or more members. */
21	    private static final int HOUSEHOLD_POINTS = 2;
22	
23	    /** Points awarded for tenure over the threshold. */
24	    private static final int TENURE_POINTS = 3;
25	
26	    /** Elapsed fiscal years that must be exceeded before the tenure points are awarded. */
27	    private static final int TENURE_THRESHOLD_FISCAL_YEARS = 1;
28	
29	    /** A household of this many members (or more) earns the household points. */
30	    private static final int GOLD_HOUSEHOLD_SIZE = 3;
31	
32	    private MembershipLevelResolver() {
33	    }
34	
35	    /**
36	     * Returns the membership points for an owner. Starts at 0, gains 2 when an
37	     * email is present (non-blank), gains 1 when the owner's name was unique on
38	     * create ({@code namesakeCount} is 0), gains 2 when the owner belongs to a
39	     * household of three or more members and gains 3 for tenure over one elapsed
40	     * fiscal year.
41	     *
42	     * @param email                the owner's email, may be {@code null}
43	     * @param namesakeCount        the owner's namesake count, may be {@code null}
44	     * @param householdMemberCount the number of owners in the owner's household, may be {@code null}
45	     * @param registrationDate     the owner's registration date, may be {@code null}
46	     * @return the membership points, zero or more
47	     */
48	    public static int deriveMembershipPoints(String email, Integer namesakeCount,
49	            Integer householdMemberCount, LocalDate registrationDate) {
50	        int points = 0;
51	        if (email != null && !email.isBlank()) {
52	            points += EMAIL_POINTS;
53	        }
54	        if (namesakeCount != null && namesakeCount == 0) {
55	            points += UNIQUE_NAME_POINTS;
56	        }
57	        if (householdMemberCount != null && householdMemberCount >= GOLD_HOUSEHOLD_SIZE) {
58	            points += HOUSEHOLD_POINTS;
59	        }
60	        if (hasTenure(registrationDate)) {
61	            points += TENURE_POINTS;
62	        }
63	        return points;
64	    }
65	
66	    /**
67	     * Returns the membership points for an owner, reading straight off it the same fields the
68	     * {@link #deriveMembershipPoints(String, Integer, Integer, LocalDate) primitive form} takes: its email, namesake
69	     * count, household member count and registration date. This is the form callers that already hold an {@link Owner}
70	     * should prefer, so the field unpacking lives in one place.
71	     *
72	     * @param owner the owner whose membership points should be derived
73	     * @return the membership points, zero or more
74	     */
75	    public static int deriveMembershipPoints(Owner owner) {
76	        return deriveMembershipPoints(owner.getEmail(), owner.getNamesakeCount(),
77	            owner.getHouseholdMemberCount(), owner.getRegistrationDate());
78	    }
79	
80	    /**
81	     * Returns the membership level for an owner, mapped from its
82	     * {@link #deriveMembershipPoints membership points}: level 1 (0-1 points),
83	     * level 2 (2-3 points), level 3 (4-5 points) and level 4 (6 or more points).
84	     *
85	     * @param email                the owner's email, may be {@code null}
86	     * @param namesakeCount        the owner's namesake count, may be {@code null}
87	     * @param householdMemberCount the number of owners in the owner's household, may be {@code null}
88	     * @param registrationDate     the owner's registration date, may be {@code null}
89	     * @return the membership level, between 1 and 4 inclusive
90	     */
91	    public static int deriveMembershipLevel(String email, Integer namesakeCount,
92	            Integer householdMemberCount, LocalDate registrationDate) {
93	        int points = deriveMembershipPoints(email, namesakeCount, householdMemberCount, registrationDate);
94	        return levelForPoints(points);
95	    }
96	
97	    /**
98	     * Returns the membership level for an owner, reading straight off it the same fields the
99	     * {@link #deriveMembershipLevel(String, Integer, Integer, LocalDate) primitive form} takes: its email, namesake
100	     * count, household member count and registration date. This is the form callers that already hold an {@link Owner}
101	     * should prefer, so the field unpacking lives in one place.
102	     *
103	     * @param owner the owner whose membership level should be derived
104	     * @return the membership level, between 1 and 4 inclusive
105	     */
106	    public static int deriveMembershipLevel(Owner owner) {
107	        return deriveMembershipLevel(owner.getEmail(), owner.getNamesakeCount(),
108	            owner.getHouseholdMemberCount(), owner.getRegistrationDate());
109	    }
110	
111	    /**
112	     * Maps membership points to a membership level: 1 (0-1), 2 (2-3), 3 (4-5), 4 (6 or more).
113	     *
114	     * @param points the owner's membership points
115	     * @return the membership level, between 1 and 4 inclusive
116	     */
117	    private static int levelForPoints(int points) {
118	        if (points >= 6) {
119	            return 4;
120	        }
121	        if (points >= 4) {
122	            return 3;
123	        }
124	        if (points >= 2) {
125	            return 2;
126	        }
127	        return 1;
128	    }
129	
130	    /**
131	     * Reports whether an owner's tenure exceeds the tenure threshold, i.e. more than one whole fiscal
132	     * year (see {@link FiscalYearResolver}) has elapsed between {@code registrationDate} and today. A
133	     * {@code null} or future registration date counts as no tenure.
134	     *
135	     * @param registrationDate the owner's registration date, may be {@code null}
136	     * @return {@code true} when more than one fiscal year has elapsed since registration
137	     */
138	    private static boolean hasTenure(LocalDate registrationDate) {
139	        if (registrationDate == null) {
140	            return false;
141	        }
142	        return FiscalYearResolver.elapsedFiscalYears(registrationDate, LocalDate.now())
143	            > TENURE_THRESHOLD_FISCAL_YEARS;
144	    }
